 for(const width of [1440,320])for(const dir of ['ltr','rtl']){await fresh({width,dir,zoom:2});await cardsReady();const layout=await page.evaluate(()=>{const region=document.querySelector('.boards-panel'),targets=[...region.querySelectorAll('button,input,select,summary')].filter(node=>node.getClientRects().length&&!node.closest('details:not([open])')),cards=[...region.querySelectorAll('.board-result')],table=region.querySelector('[role="region"][tabindex="0"]');return{viewport:innerWidth,documentWidth:document.documentElement.scrollWidth,targets:targets.map(node=>({text:node.textContent?.slice(0,80)||node.type,height:node.getBoundingClientRect().height/Number(getComputedStyle(document.body).zoom||1)})),columns:getComputedStyle(region.querySelector('.board-row')).gridTemplateColumns,cards:cards.map(node=>({width:node.clientWidth,scrollWidth:node.scrollWidth})),scroll:table?{width:table.clientWidth,scrollWidth:table.scrollWidth}:null,color:getComputedStyle(cards[0]).color,hintColor:getComputedStyle(cards[0].querySelector('.hint')).color,background:getComputedStyle(cards[0]).backgroundColor};});evidence.layout.push({width,dir,bodyCssZoom:2,...layout});save();assert.ok(layout.documentWidth<=layout.viewport,'Document stays contained while tables scroll internally');assert.ok(layout.targets.every(target=>target.height>=43.9),'Native action/date controls retain44CSSpx targets');if(width===320){assert.equal(layout.columns.trim().split(/\s+/).length,1);assert.ok(layout.scroll.scrollWidth>layout.scroll.width,'Wide native tables keep readable columns in their focusable internal scroller');}const scroller=panel().getByRole('region',{name:'Funnel conversion steps',exact:true});await scroller.focus();assert.equal(await scroller.evaluate(node=>node===document.activeElement),true);await page.keyboard.press('ArrowRight');const luminance=value=>{const parts=value.match(/[0-9.]+/g).map(Number);assert.ok(parts.length===3||parts[3]===1,'Contrast uses an opaque actual computed color');const channels=parts.slice(0,3).map(n=>{const v=n/255;return v<=0.04045?v/12.92:((v+0.055)/1.055)**2.4;});return channels[0]*0.2126+channels[1]*0.7152+channels[2]*0.0722;};for(const foreground of [layout.color,layout.hintColor]){const a=luminance(foreground),b=luminance(layout.background);assert.ok((Math.max(a,b)+0.05)/(Math.min(a,b)+0.05)>=4.5,'Actual card text and hint colors meet4.5:1 contrast');}const shot=out+'/boards-'+width+'-'+dir+'-bodyzoom2.png';await page.screenshot({path:shot,fullPage:true});evidence.screenshots.push(shot);save();}pass('desktop/mobile LTR/RTL CSS-body-zoom2 keeps44px controls, saved reading order and keyboard internal tables without crushed columns');

