assert.equal(evidence.groups.length,21);assert.equal(evidence.contexts,108);assert.equal(evidence.screenshots.length,8);assert.deepEqual(evidence.external,[]);assert.deepEqual(evidence.unexpected,[]);assert.deepEqual(evidence.pageErrors,[]);assert.deepEqual(pins(),before);evidence.sourceBefore=before;evidence.sourceAfter=pins();evidence.phase='passed';save();console.log('BOARDS_BROWSER_PASSED '+JSON.stringify({groups:evidence.groups.length,contexts:evidence.contexts,requests:evidence.requests.length,posts:posts().length,screenshots:evidence.screenshots.length,evidence:out+'/evidence.json'}));
